(function(){
 function replace(){document.querySelectorAll('img[src^="images/"]').forEach(function(img){
  var key=img.getAttribute('src'),src=window.GUIDE_ASSETS[key];
  if(src){img.src=src;}
 });}
 if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',replace);
 else replace();
})();
